"""第二人：全文 → 摘要 → 無可用證據的單一入口（不連網）。

重點：
1. 順序正確，拿到全文就不浪費一次 Semantic Scholar 額度
2. 同一筆 ref 只解析一次，方法 A 和方法 B 拿到同一份證據
3. 全文和摘要各自為什麼沒拿到要分開寫，不可以併成一句「查詢失敗」
"""

import pytest

from src.adapters import ReferenceLookupResult
from src.fulltext_sources import FullTextResult, FullTextStatus, ManualUpload
from src.schemas import CitationPair, EvidenceBasis, SourceStatus
from src.source_evidence import EvidenceResolver

_LEADING = __import__("re").compile(r"^\[\d+\]\s*")

REF = ("[1] W. H. Walters and E. I. Wilder, “Fabrication and errors in the bibliographic "
       "citations generated by ChatGPT,” Sci. Rep., vol. 13, 2023, "
       "doi: 10.1038/s41598-023-41032-5.")


def pair(ref_number: int = 1) -> CitationPair:
    # production 的 ref_raw 帶自己的編號前綴（實測 build_citation_pairs），
    # fixture 不帶的話，跨編號共用快取的測試會替一個不存在的行為背書
    raw = _LEADING.sub(f"[{ref_number}] ", REF)
    return CitationPair(pair_id=f"p{ref_number}", claim_text="ChatGPT 會捏造引用。",
                        citation_marker=f"[{ref_number}]", ref_number=ref_number, ref_raw=raw)


class FakeFetcher:
    def __init__(self, result: FullTextResult, by_doi: dict[str, FullTextResult] | None = None,
                 *, upload_result: FullTextResult | None = None,
                 upload_error: Exception | None = None) -> None:
        self.result = result
        self.by_doi = by_doi or {}
        self.calls = 0
        self.seen: list[str] = []
        self.upload_result = upload_result
        self.upload_error = upload_error
        self.uploads: list[tuple[str, bytes, str]] = []

    def fetch(self, meta):
        self.calls += 1
        self.seen.append(meta.doi or meta.arxiv_id or meta.title)
        return self.by_doi.get(meta.doi, self.result)

    def fetch_upload(self, name: str, data: bytes, *, label: str = "",
                     min_chars: int | None = None) -> FullTextResult:
        # 簽名要跟著真的 FullTextFetcher.fetch_upload 走，否則之後 resolver 開始
        # 轉傳 min_chars 時，這個替身會以 TypeError 炸掉而不是測出行為差異
        self.uploads.append((name, data, label))
        if self.upload_error is not None:
            raise self.upload_error
        assert self.upload_result is not None, "測試忘了給 upload_result"
        return self.upload_result


class FakeLookup:
    def __init__(self, result: ReferenceLookupResult) -> None:
        self.result = result
        self.calls = 0
        self.seen: list[str] = []

    def lookup(self, pair: CitationPair) -> ReferenceLookupResult:
        self.calls += 1
        self.seen.append(pair.ref_raw)
        return self.result


def full_text_ok() -> FullTextResult:
    return FullTextResult(status=FullTextStatus.GOT_FULL_TEXT, markdown="# Paper\n\nBody.",
                          source="europe_pmc_xml", url="https://example.org/x",
                          converter="jats", note="")


def abstract_ok() -> ReferenceLookupResult:
    return ReferenceLookupResult(ref_number=1, title="Fabrication and errors",
                                 abstract="We checked 636 citations.",
                                 source_status=SourceStatus.GOT_ABSTRACT,
                                 abstract_source="semantic_scholar",
                                 abstract_url="https://api.semanticscholar.org/x",
                                 source_note="Semantic Scholar 用 DOI 找到")


def test_full_text_wins_and_skips_the_abstract_lookup():
    fetcher, lookup = FakeFetcher(full_text_ok()), FakeLookup(abstract_ok())

    evidence = EvidenceResolver(fetcher, lookup).resolve(pair())

    assert evidence.basis is EvidenceBasis.FULL_TEXT
    assert evidence.text == "# Paper\n\nBody."
    assert evidence.source == "europe_pmc_xml"
    assert evidence.converter == "jats"
    assert evidence.has_evidence is True
    assert lookup.calls == 0  # 拿到全文就不要再花一次查摘要的額度


def test_falls_back_to_the_abstract_when_there_is_no_full_text():
    fetcher = FakeFetcher(FullTextResult(status=FullTextStatus.NO_OPEN_ACCESS,
                                         note="沒有可用的開放存取位置"))
    lookup = FakeLookup(abstract_ok())

    evidence = EvidenceResolver(fetcher, lookup).resolve(pair())

    assert evidence.basis is EvidenceBasis.ABSTRACT
    assert evidence.text == "We checked 636 citations."
    assert evidence.source == "semantic_scholar"
    assert evidence.converter == ""
    assert lookup.calls == 1


def test_no_evidence_at_all_is_marked_unverifiable():
    fetcher = FakeFetcher(FullTextResult(status=FullTextStatus.NO_OPEN_ACCESS))
    lookup = FakeLookup(ReferenceLookupResult(ref_number=1, title="t",
                                              source_status=SourceStatus.NOT_FOUND,
                                              source_note="兩個資料庫都查無"))

    evidence = EvidenceResolver(fetcher, lookup).resolve(pair())

    assert evidence.basis is EvidenceBasis.UNAVAILABLE
    assert evidence.unverifiable is True
    assert evidence.text == ""


def test_note_keeps_the_two_reasons_apart():
    """下載失敗和查不到是兩件事，不可以併成一句。"""

    fetcher = FakeFetcher(FullTextResult(status=FullTextStatus.FETCH_FAILED,
                                         note="PDF 下載失敗（HTTP 429）"))
    lookup = FakeLookup(ReferenceLookupResult(ref_number=1, title="t",
                                              source_status=SourceStatus.LOOKUP_FAILED,
                                              source_note="Semantic Scholar 限流"))

    evidence = EvidenceResolver(fetcher, lookup).resolve(pair())

    assert "全文：全文下載失敗（PDF 下載失敗（HTTP 429））" in evidence.note
    assert "摘要：查詢失敗（Semantic Scholar 限流）" in evidence.note
    assert evidence.unverifiable is True


def test_missing_converter_still_falls_back_to_the_abstract():
    """缺 docling 是我們的問題，note 要講得出來，不可以只說沒有全文。"""

    fetcher = FakeFetcher(FullTextResult(status=FullTextStatus.NO_CONVERTER,
                                         source="oa_pdf", url="https://example.org/a.pdf",
                                         note="本機沒有安裝 docling，PDF 轉不了（不是文獻的問題）"))
    lookup = FakeLookup(abstract_ok())

    evidence = EvidenceResolver(fetcher, lookup).resolve(pair())

    assert evidence.basis is EvidenceBasis.ABSTRACT  # 仍然退摘要，不是直接放棄
    assert "缺少轉檔工具" in evidence.note
    assert "docling" in evidence.note


def test_both_methods_get_the_same_evidence():
    """同一筆 ref 只解析一次；A、B 拿到不同證據正是 11/24 分歧的來源之一。"""

    fetcher, lookup = FakeFetcher(full_text_ok()), FakeLookup(abstract_ok())
    resolver = EvidenceResolver(fetcher, lookup)

    for_method_a = resolver.resolve(pair())
    for_method_b = resolver.resolve(pair())

    assert for_method_a == for_method_b  # 評估腳本要能用 == 自我檢查 A／B 證據一致
    assert for_method_a.text == for_method_b.text
    assert for_method_a.basis is for_method_b.basis
    assert for_method_b.reused is True
    assert fetcher.calls == 1
    assert lookup.calls == 0


ISIK_REF = ("[1] M. Isik and S. Guleryuzlu, “A large language model pipeline for automated "
            "citation quality scoring,” Sci. Rep., vol. 16, 2026, doi: 10.1038/s41598-026-60947-3.")


def test_same_reference_under_two_numbers_is_resolved_once():
    """同一份書目被登錄成 [1] 和 [17]，不該查兩次。"""

    fetcher, lookup = FakeFetcher(full_text_ok()), FakeLookup(abstract_ok())
    resolver = EvidenceResolver(fetcher, lookup)

    resolver.resolve(pair(1))
    resolver.resolve(pair(17))

    assert fetcher.calls == 1


def test_same_ref_number_in_a_different_paper_is_not_reused():
    """最嚴重的那個 bug：跑第二篇論文時，它的 [1] 不可以拿到第一篇 [1] 的全文。"""

    walters = FullTextResult(status=FullTextStatus.GOT_FULL_TEXT, markdown="WALTERS FULL TEXT",
                             source="europe_pmc_xml", url="u1", converter="jats")
    isik = FullTextResult(status=FullTextStatus.GOT_FULL_TEXT, markdown="ISIK FULL TEXT",
                          source="oa_pdf", url="u2", converter="docling")
    fetcher = FakeFetcher(walters, by_doi={"10.1038/s41598-026-60947-3": isik})
    resolver = EvidenceResolver(fetcher, FakeLookup(abstract_ok()))

    first = resolver.resolve(pair(1))
    second = resolver.resolve(CitationPair(pair_id="b1", claim_text="x", citation_marker="[1]",
                                           ref_number=1, ref_raw=ISIK_REF))

    assert first.text == "WALTERS FULL TEXT"
    assert second.text == "ISIK FULL TEXT"
    assert second.reused is False
    assert fetcher.calls == 2


def test_the_fetcher_receives_this_pair_s_own_bibliography():
    fetcher = FakeFetcher(full_text_ok())
    EvidenceResolver(fetcher, FakeLookup(abstract_ok())).resolve(pair())

    assert fetcher.seen == ["10.1038/s41598-023-41032-5"]


def test_clear_allows_a_retry_after_a_transient_failure():
    """限流後重試：失敗會被記住（A、B 要同一份），所以要先 clear 才查得到。"""

    class Flaky:
        def __init__(self) -> None:
            self.calls = 0

        def fetch(self, meta):
            self.calls += 1
            if self.calls == 1:
                return FullTextResult(status=FullTextStatus.FETCH_FAILED, note="HTTP 429")
            return full_text_ok()

    fetcher = Flaky()
    lookup = FakeLookup(ReferenceLookupResult(ref_number=1, title="t",
                                              source_status=SourceStatus.LOOKUP_FAILED))
    resolver = EvidenceResolver(fetcher, lookup)

    assert resolver.resolve(pair()).unverifiable is True
    assert resolver.resolve(pair()).unverifiable is True  # 同一次執行內 A、B 看到同一份
    resolver.clear()

    assert resolver.resolve(pair()).basis is EvidenceBasis.FULL_TEXT


def test_a_string_source_status_does_not_crash_the_note():
    """adapter 從 JSON 還原時 source_status 可能是純字串，不可以讓 resolve 炸掉。"""

    fetcher = FakeFetcher(FullTextResult(status=FullTextStatus.NO_OPEN_ACCESS))
    broken = ReferenceLookupResult(ref_number=1, title="t", abstract="an abstract",
                                   source_status="拿到摘要")  # type: ignore[arg-type]

    evidence = EvidenceResolver(fetcher, FakeLookup(broken)).resolve(pair())

    assert evidence.basis is EvidenceBasis.ABSTRACT
    assert "拿到摘要" in evidence.note


