@pytest.mark.parametrize("failing", ["fulltext", "lookup"])
def test_unexpected_exceptions_do_not_escape(failing: str):
    class Exploding:
        def fetch(self, meta):
            raise RuntimeError("boom")

        def lookup(self, pair):
            raise RuntimeError("boom")

    fetcher = Exploding() if failing == "fulltext" else FakeFetcher(
        FullTextResult(status=FullTextStatus.NO_OPEN_ACCESS))
    lookup = Exploding() if failing == "lookup" else FakeLookup(
        ReferenceLookupResult(ref_number=1, title="t", source_status=SourceStatus.NOT_FOUND))

    evidence = EvidenceResolver(fetcher, lookup).resolve(pair())

    assert evidence.unverifiable is True
    assert "RuntimeError" in evidence.note


