# ---------- 沒有識別碼時用 Crossref 比對補上（2026-11-28） ----------
# 實測：7,294 筆真實書目裡本機 regex 只抽得到 26% 的篇名，作者年份制沒有統一標準。
# 比對層把整條原文丟給 Crossref，再用本機抽到的作者與年份獨立驗證。

NO_DOI_REF = ("Anna Abalkina and Dorothy Bishop. 2023. Paper mills: a novel form of "
              "publishing malpractice affecting psychology. Meta-Psychology, 7.")


def no_doi_pair() -> CitationPair:
    return CitationPair(pair_id="p9", claim_text="論文工廠是一種新型態的出版不當行為。",
                        citation_marker="(Abalkina & Bishop, 2023)", ref_number=9,
                        ref_raw=NO_DOI_REF)


class FakeHttp:
    def __init__(self, item: dict | None, *, status: int = 200, error: str = "") -> None:
        self.item, self.status, self.error = item, status, error
        self.calls: list[dict] = []

    def get(self, url, params=None, headers=None):
        self.calls.append(params or {})
        if self.error or self.status != 200:
            return self.status, None, self.error
        return 200, {"message": {"items": [self.item] if self.item else []}}, ""


def crossref_item(score=150.0, families=("Abalkina", "Bishop")):
    return {"title": ["Paper mills: a novel form of publishing malpractice affecting psychology"],
            "score": score, "DOI": "10.15626/MP.2022.3422",
            "issued": {"date-parts": [[2023]]},
            "author": [{"family": f} for f in families]}


def matching_resolver(http, *, full=None, **kwargs):
    lookup = FakeLookup(abstract_ok())
    lookup.http = http
    fetcher = FakeFetcher(full or FullTextResult(status=FullTextStatus.NO_IDENTIFIER))
    return EvidenceResolver(fetcher, lookup, **kwargs), fetcher, lookup


def test_a_confirmed_match_supplies_the_doi_to_the_full_text_fetcher():
    """比對的真正價值是拿到 DOI：有 DOI 才查得到開放存取位置。"""
    http = FakeHttp(crossref_item())
    resolver, fetcher, _ = matching_resolver(http)

    evidence = resolver.resolve(no_doi_pair())

    assert fetcher.seen == ["10.15626/mp.2022.3422"], "取全文那層要收到比對補上的 DOI"
    assert "書目比對" in evidence.note
    assert len(http.calls) == 1


def test_a_reference_that_already_has_a_doi_is_not_sent_to_crossref():
    """有識別碼就不要浪費一次請求，Crossref 公開池每秒只能一次。"""
    http = FakeHttp(crossref_item())
    resolver, _, _ = matching_resolver(http, full=full_text_ok())

    resolver.resolve(pair())

    assert http.calls == []


def test_an_unconfirmed_match_leaves_the_metadata_alone_and_says_why():
    http = FakeHttp(crossref_item(families=("Totally", "Different")))
    resolver, fetcher, _ = matching_resolver(http)

    evidence = resolver.resolve(no_doi_pair())

    assert fetcher.seen == [""] or "10.15626" not in fetcher.seen[0], "沒驗證過的 DOI 不可以用"
    assert "書目比對未採用" in evidence.note
    assert "第一作者" in evidence.note


def test_a_broken_matcher_does_not_fail_the_whole_resolution():
    """比對層壞掉要退回本機解析，不可以讓整筆取證失敗。"""
    http = FakeHttp(None, status=500, error="boom")
    resolver, _, _ = matching_resolver(http)

    evidence = resolver.resolve(no_doi_pair())

    assert evidence.basis in (EvidenceBasis.ABSTRACT, EvidenceBasis.UNAVAILABLE)
    assert "書目比對未採用" in evidence.note


def test_the_same_reference_is_only_matched_once():
    http = FakeHttp(crossref_item())
    resolver, _, _ = matching_resolver(http)

    resolver.resolve(no_doi_pair())
    resolver.clear()                      # 清掉證據快取，比對結果仍要沿用
    resolver.resolve(no_doi_pair())

    assert len(http.calls) == 1, "同一條書目不可以查兩次 Crossref"


def test_matching_can_be_turned_off():
    http = FakeHttp(crossref_item())
    resolver, _, _ = matching_resolver(http, match_references=False)

    evidence = resolver.resolve(no_doi_pair())

    assert http.calls == []
    assert "書目比對" not in evidence.note


def test_a_matcher_that_raises_does_not_fail_the_whole_resolution():
    """HTTP 錯誤比對層自己會處理；這裡測的是它**自己壞掉**（丟例外）的情況。"""
    class Exploding:
        calls = 0

        def get(self, url, params=None, headers=None):
            Exploding.calls += 1
            raise RuntimeError("boom")

    lookup = FakeLookup(abstract_ok())
    lookup.http = Exploding()
    resolver = EvidenceResolver(FakeFetcher(FullTextResult(status=FullTextStatus.NO_IDENTIFIER)), lookup)

    evidence = resolver.resolve(no_doi_pair())

    assert Exploding.calls == 1
    assert "書目比對發生錯誤（RuntimeError）" in evidence.note
    assert evidence.basis in (EvidenceBasis.ABSTRACT, EvidenceBasis.UNAVAILABLE)


# ------------------------------------------------- 手動上傳（分工：備援）


UPLOAD = ManualUpload(name="walters.pdf", data=b"%PDF-1.4 ...", label="walters.pdf")


def upload_ok() -> FullTextResult:
    return FullTextResult(status=FullTextStatus.GOT_FULL_TEXT,
                          markdown="# Fabrication and errors\n\n636 citations were checked.",
                          source="manual_upload", url="walters.pdf", converter="docling")


def test_a_manual_upload_is_used_instead_of_going_online():
    fetcher = FakeFetcher(full_text_ok(), upload_result=upload_ok())
    lookup = FakeLookup(abstract_ok())

    evidence = EvidenceResolver(fetcher, lookup,
                                manual_uploads={1: UPLOAD}).resolve(pair())

    assert evidence.basis is EvidenceBasis.FULL_TEXT
    assert evidence.text.startswith("# Fabrication and errors")
    assert evidence.source == "manual_upload"
    assert evidence.converter == "docling"
    assert fetcher.calls == 0   # 不可以再去自動取全文
    assert lookup.calls == 0    # 也不可以再花一次查摘要的額度
    assert fetcher.uploads == [("walters.pdf", b"%PDF-1.4 ...", "walters.pdf")]


def test_the_note_says_the_evidence_came_from_an_upload():
    fetcher = FakeFetcher(full_text_ok(), upload_result=upload_ok())

    evidence = EvidenceResolver(fetcher, FakeLookup(abstract_ok()),
                                manual_uploads={1: UPLOAD}).resolve(pair())

    # 評估時要分得出這筆證據是人給的，不是系統自己找到的
    assert "手動上傳" in evidence.note
    assert "walters.pdf" in evidence.note


def test_an_upload_that_will_not_convert_falls_back_to_the_automatic_route():
    fetcher = FakeFetcher(
        full_text_ok(),
        upload_result=FullTextResult(status=FullTextStatus.CONVERT_FAILED,
                                     source="manual_upload", note="docling 轉出來是空的"),
    )

    evidence = EvidenceResolver(fetcher, FakeLookup(abstract_ok()),
                                manual_uploads={1: UPLOAD}).resolve(pair())

    assert evidence.basis is EvidenceBasis.FULL_TEXT
    assert evidence.source == "europe_pmc_xml"   # 退回自動取得的那一份
    assert fetcher.calls == 1
    # 失敗原因一定要留著，否則畫面看起來像使用者根本沒上傳
    assert "手動上傳（walters.pdf）沒能用" in evidence.note
    assert "全文轉檔失敗" in evidence.note


def test_an_upload_that_fails_is_still_reported_when_nothing_else_works():
    fetcher = FakeFetcher(
        FullTextResult(status=FullTextStatus.NO_OPEN_ACCESS),
        upload_result=FullTextResult(status=FullTextStatus.CONVERT_FAILED,
                                     source="manual_upload", note="不支援的副檔名「.docx」"),
    )
    lookup = FakeLookup(ReferenceLookupResult(ref_number=1, title="t",
                                              source_status=SourceStatus.NOT_FOUND,
                                              source_note="兩個資料庫都查無"))

    evidence = EvidenceResolver(fetcher, lookup, manual_uploads={1: UPLOAD}).resolve(pair())

    assert evidence.basis is EvidenceBasis.UNAVAILABLE
    assert evidence.unverifiable is True
    # 三個原因要分開寫：上傳轉不了、沒有開放存取、查不到摘要
    assert "手動上傳（walters.pdf）沒能用" in evidence.note
    assert "不支援的副檔名" in evidence.note
    assert "沒有開放存取全文" in evidence.note
    assert "文獻查不到" in evidence.note or "兩個資料庫都查無" in evidence.note


