def test_an_upload_beats_an_automatic_result_already_in_the_cache():
    """另一條 ref 先把同一份書目自動取回來了，也不可以蓋過這一條的上傳。

    兩條 ref 指到同一篇文獻時，先解析的那條會把自動取得的全文寫進快取。
    快取的鍵是書目，所以後面那條如果直接吃快取，使用者上傳的檔案就等於沒作用。
    """

    fetcher = FakeFetcher(full_text_ok(), upload_result=upload_ok())
    resolver = EvidenceResolver(fetcher, FakeLookup(abstract_ok()),
                                manual_uploads={2: UPLOAD})

    automatic = resolver.resolve(pair(1))   # 沒有上傳，走自動，寫進快取
    manual = resolver.resolve(pair(2))      # 同一條書目，但這一條有上傳

    assert automatic.source == "europe_pmc_xml"
    assert manual.source == "manual_upload"
    assert manual.text.startswith("# Fabrication and errors")


def test_replacing_an_upload_replaces_the_evidence():
    """換檔案要換得掉。舊的那份已經以 manual_upload 的身分進快取了。"""

    second = FullTextResult(status=FullTextStatus.GOT_FULL_TEXT,
                            markdown="# Corrected scan\n\nThe right paper this time.",
                            source="manual_upload", url="correct.pdf", converter="docling")
    fetcher = FakeFetcher(full_text_ok(), upload_result=upload_ok())
    resolver = EvidenceResolver(fetcher, FakeLookup(abstract_ok()),
                                manual_uploads={1: UPLOAD})

    first = resolver.resolve(pair())
    fetcher.upload_result = second
    resolver.add_manual_upload(1, ManualUpload(name="correct.pdf", data=b"%PDF-1.4 other"))
    replaced = resolver.resolve(pair())

    assert first.text.startswith("# Fabrication and errors")
    assert replaced.text.startswith("# Corrected scan")
    assert "correct.pdf" in replaced.note


class RecordingHttp:
    """記下每一次外部請求。_match 會吞掉例外，所以用計次而不是用丟錯來驗。"""

    def __init__(self) -> None:
        self.calls: list[str] = []

    def get(self, url, params=None, headers=None):
        self.calls.append(url)
        return 500, None, "測試：不該走到這裡"


# 沒有 DOI、沒有 arXiv ID：這種書目才會觸發 Crossref 比對，才測得到「不連網」
NO_ID_REF = '[1] A. Author, "A study of treatment time," J. Care, 2026.'


def no_id_pair(ref_number: int = 1) -> CitationPair:
    return CitationPair(pair_id=f"p{ref_number}", claim_text="治療時間縮短。",
                        citation_marker=f"[{ref_number}]", ref_number=ref_number,
                        ref_raw=_LEADING.sub(f"[{ref_number}] ", NO_ID_REF))


def test_a_reference_without_an_identifier_normally_goes_to_crossref():
    """對照組：沒有上傳時，同一條書目真的會送出比對請求。

    沒有這一條的話，下面那個「不連網」的測試可能只是因為這條書目本來就不會比對。
    """

    lookup = FakeLookup(abstract_ok())
    lookup.http = RecordingHttp()

    EvidenceResolver(FakeFetcher(full_text_ok()), lookup).resolve(no_id_pair())

    assert lookup.http.calls, "沒有上傳時應該會打一次 Crossref 比對"


def test_an_uploaded_reference_makes_no_external_request_at_all():
    fetcher = FakeFetcher(full_text_ok(), upload_result=upload_ok())
    lookup = FakeLookup(abstract_ok())
    lookup.http = RecordingHttp()      # 書目比對會用 lookup.http
    resolver = EvidenceResolver(fetcher, lookup, manual_uploads={1: UPLOAD})

    evidence = resolver.resolve(no_id_pair())

    assert evidence.source == "manual_upload"
    assert lookup.http.calls == []     # 不可以打 Crossref
    assert fetcher.calls == 0          # 不可以去抓全文
    assert lookup.calls == 0           # 不可以查摘要


def test_an_upload_beats_a_cached_automatic_result_for_a_reference_without_a_doi():
    """書目沒有識別碼時，自動結果和手動結果會共用同一個快取鍵。

    這種書目的快取鍵會退回整條原文，剛好就是手動上傳用的那一個。只看「有沒有
    快取」就回傳的話，先解析的那條 ref 會把自動結果留在那裡，後面有上傳的那條
    就拿到別人自動抓來的內容，使用者的檔案等於沒作用。
    """

    fetcher = FakeFetcher(full_text_ok(), upload_result=upload_ok())
    lookup = FakeLookup(abstract_ok())
    lookup.http = RecordingHttp()
    resolver = EvidenceResolver(fetcher, lookup, manual_uploads={2: UPLOAD})

    automatic = resolver.resolve(no_id_pair(1))
    manual = resolver.resolve(no_id_pair(2))

    assert automatic.source == "europe_pmc_xml"
    assert manual.source == "manual_upload"


