def test_a_generic_entry_does_not_share_its_upload_with_another_reference():
    """``[13] Ibid.`` 與 ``[14] Ibid.`` 逐字相同，卻是兩篇不同的文獻。

    快取鍵去掉編號是為了讓「同一篇文獻被引用兩次」共用一次上傳；但認不出是哪一篇
    的書目不可以共用，否則上傳給 [13] 的檔案會變成 [14] 的證據，而使用者從來沒有
    為 [14] 指定任何檔案——那就是拿別篇論文的全文去比對。
    """

    def ibid(ref_number: int) -> CitationPair:
        return CitationPair(pair_id=f"p{ref_number}", claim_text="前述研究指出治療時間縮短。",
                            citation_marker=f"[{ref_number}]", ref_number=ref_number,
                            ref_raw=f"[{ref_number}] Ibid.")

    fetcher = FakeFetcher(FullTextResult(status=FullTextStatus.NO_IDENTIFIER),
                          upload_result=upload_ok())
    lookup = FakeLookup(ReferenceLookupResult(ref_number=1, title="",
                                              source_status=SourceStatus.NOT_FOUND))
    lookup.http = RecordingHttp()
    resolver = EvidenceResolver(fetcher, lookup, manual_uploads={13: UPLOAD})

    given = resolver.resolve(ibid(13))
    other = resolver.resolve(ibid(14))

    assert given.source == "manual_upload"
    assert other.source != "manual_upload"
    assert other.unverifiable is True


